struct buf { _Atomic unsigned refs; size_t len; char *data; };

static struct buf *buf_new(size_t n) {
    struct buf *b = malloc(sizeof *b + n);
    atomic_init(&b->refs, 1); b->len = n; b->data = (char *)(b + 1);
    return b;
}
struct buf *buf_ref(struct buf *b) { atomic_fetch_add(&b->refs, 1); return b; }
void buf_unref(struct buf *b) {
    if (atomic_fetch_sub(&b->refs, 1) == 1) free(b);
}
